  cards: [{ q: 'Do ktorého mora odteká väčšina slovenských riek?', a: 'Do Čierneho mora.' }, { q: 'Ktoré rieky patria do úmoria Baltského mora?', a: 'Poprad a Dunajec.' }, { q: 'Ktorá je najdlhšia rieka, ktorá tečie celá na Slovensku?', a: 'Váh.' }, { q: 'Kedy majú rieky spravidla najviac vody?', a: 'Na jar, keď sa topí sneh.' }, { q: 'Cez ktorú rieku tečie Bodrog do Dunaja?', a: 'Cez Tisu.', l: 2 }, { q: 'Kde je najnižšie miesto Slovenska?', a: 'Pri Bodrogu v Kline nad Bodrogom, asi 94 m n. m.', l: 2 }],
